def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G

G=load()

inp=G.get('Test input')
rows, cols = 22, 26

# Find ALL non-zero unique colors in test input
all_colors = set()
for r in range(rows):
    for c in range(cols):
        if inp[r][c] != 0:
            all_colors.add(inp[r][c])

print("=== All colors in Test Input ===", sorted(all_colors))

# Check if these colors form complete rectangles or are just scattered
def find_frames(grid, rows, cols):
    """Find rectangular frames (closed borders of single color)"""
    frames = []
    for color in grid[0]:
        if color == 0:
            continue

        # Find min/max bounds
        min_r, max_r, min_c, max_c = rows, 0, cols, 0
        has_border = True

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == color:
                    min_r = min(min_r, r)
                    max_r = max(max_r, r)
                    min_c = min(min_c, c)
                    max_c = max(max_c, c)

        # Check if this forms a complete rectangular frame
        for r in range(min_r, max_r + 1):
            for c in range(min_c, max_c + 1):
                if grid[r][c] != color:
                    has_border = False
                    break

        if has_border and (max_r - min_r + 1 >= 2 and max_c - min_c + 1 >= 2):
            frames.append({'color': color, 'r_top': min_r, 'r_bottom': max_r, 
                          'c_left': min_c, 'c_right': max_c})

    return frames

frames_test = find_frames(inp, rows, cols)
print("\n=== Frames found in Test Input ===")
for i, f in enumerate(frames_test):
    print(f"  Frame {i+1}: border={f['color']}, r[{f['r_top']}-{f['r_bottom']}], c[{f['c_left']}-{f['c_right']}]")

# Check remaining colors that don't form frames
frame_colors = {f['color'] for f in frames_test}
non_frame_colors = all_colors - frame_colors - {0}
print("\n=== Non-frame colors (potential fill colors): ===", sorted(non_frame_colors))

